const acc = {};
for (const item of items) {
  const row = item.json || {};
  if (!row.key) continue;
  acc[row.key] = row.value;
}
return [{ json: acc }];

const cfg = $('Config').item.json;
const body = $('Temp Webhook Body').item.json || {};
const tz = cfg.tz || 'Asia/Ho_Chi_Minh';
const rawDate = body.date || $now.setZone(tz).toISODate();
const dt = DateTime.fromISO(rawDate, { zone: tz });
const target = dt.isValid ? dt : $now.setZone(tz);
return [{
  json: {
    ...cfg,
    ...$json,
    targetDate: target.toISODate(),
    dayStart: target.startOf('day').toISO(),
    dayEnd: target.endOf('day').toISO(),
    errors: [],
    tasks_created: 0,
    tasks_updated: 0,
    tasks_completed: 0,
    tickets_auto_closed: 0,
    doubleRunWarning: false
  }
}];

const cfg = $('Resolve Date').item.json;
const sysCfg = $('Merge System Config').item.json;
const rawPattern = sysCfg.daily_meeting_title_pattern || cfg.dailyMeetingTitlePattern || 'Daily WIP';
const events = items.map(i => i.json);
let matcher;
try { matcher = new RegExp(rawPattern, 'i'); }
catch (e) { matcher = new RegExp(String(rawPattern).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i'); }
const matched = events.filter(e => matcher.test(e.summary || e.title || ''));
if (!matched.length) return [{ json: { ...cfg, meetingFound: false, summaryStatus: 'no_meeting' } }];
return matched.map(event => ({ json: {
  ...cfg, ...event, event,
  meetingFound: true,
  calendar_event_id: event.id,
  title: event.summary || event.title || 'Daily WIP',
  start_time: event.start?.dateTime || event.start?.date || null,
  end_time: event.end?.dateTime || event.end?.date || null,
  attendees: event.attendees || []
} }));

const sysCfg = $('Merge System Config').item.json;
const rawPattern = sysCfg.transcript_title_pattern || 'Transcript';
let titleMatcher;
try { titleMatcher = new RegExp(rawPattern, 'i'); }
catch (e) { titleMatcher = new RegExp(String(rawPattern).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i'); }

const out = [];
for (const it of items) {
  const base = it.json;
  if (base.meetingFound === false) { out.push({ json: base }); continue; }
  const event = base.event || base;
  const attachments = event.attachments || [];
  const candidates = attachments.filter(a =>
    /application\/vnd\.google-apps\.document/i.test(a.mimeType || '')
    && titleMatcher.test(a.title || a.name || '')
  );
  if (!candidates.length) {
    out.push({ json: { ...base, hasTranscriptDoc: false, summaryStatus: 'no_transcript', docId: null } });
    continue;
  }
  for (const att of candidates) {
    out.push({ json: {
      ...base,
      hasTranscriptDoc: true,
      docId: att.fileId || att.id,
      attachmentTitle: att.title || att.name || '',
      fileUrl: att.fileUrl || att.webViewLink || null,
      transcript_url: att.fileUrl || att.webViewLink || null,
      transcript_attachment_id: att.fileId || att.id
    } });
  }
}
return out;

const source = $input.first().json.content
let text = String(source || '');
let startIndex = text.lastIndexOf('📖 Transcript');
if (startIndex >= 0) text = text.slice(startIndex);
text = text
  .replace(/^.*?📖 Transcript\s*/s, '')
  .replace(/Transcript may contain errors[\s\S]*$/i, '')
  .replace(/This editable transcript was computer generated[\s\S]*$/i, '')
  .replace(/\b\d{1,2}:\d{2}(?::\d{2})?\b/g, '')
  .replace(/^\s*(Speaker \d+|Unknown Speaker|[A-Z][A-Za-z .'-]{1,40})\s*:\s*/gm, '$1: ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
return [{ json: { ...$('Extract Candidate Attachments').item.json, transcript: text } }];

const base = $('Clean Transcript').item.json;
const cfg = $('Resolve Date').item.json;
const grouped = new Map();
for (const item of items) {
  const r = item.json || {};
  const pc = r.project_client || 'Internal';
  if (!grouped.has(pc)) grouped.set(pc, []);
  grouped.get(pc).push({
    id: r.id, task: r.task, lead: r.lead, status: r.status,
    latest_note: r.latest_note || r.note || '', next_step: r.next_step
  });
}
const projects = [...grouped.entries()].map(([project_client, tasks]) => ({ project_client, tasks }));

const dt = DateTime.fromISO(cfg.targetDate);
const todayTag = dt.toFormat('dd MMM');

const userPrompt = `TARGET_DATE: ${cfg.targetDate}
NOTE_TAG: [${todayTag}]

TRANSCRIPT:
${base.transcript}

ACTIVE PROJECTS AND THEIR CURRENT TASKS:
${JSON.stringify(projects, null, 2)}

OUTPUT FORMAT (strict JSON):
{
  "mentioned_projects": [
    {
      "project_client": "Exact project_client string from list above",
      "actions": [
        {
          "action": "update",
          "existing_task_id": "uuid-from-tasks-list",
          "task": "exact task title from list",
          "status": "in_progress",
          "latest_note": "[${todayTag}] discussed progress on...",
          "next_step": "deploy to staging by Friday",
          "lead": "Truc"
        },
        {
          "action": "create",
          "task": "Set up monitoring for new API endpoint",
          "status": "to_do",
          "latest_note": "[${todayTag}] mentioned need for monitoring",
          "next_step": "configure Datadog alerts",
          "lead": "Sang"
        },
        {
          "action": "complete",
          "existing_task_id": "uuid-from-tasks-list",
          "task": "exact task title from list"
        }
      ]
    }
  ]
}

If no active projects are mentioned, return: {"mentioned_projects": []}
Omit fields not explicitly changed in the transcript.`;

return [{ json: {
  ...base, projects,
  project_client_list: projects.map(p => p.project_client),
  targetDate: cfg.targetDate, todayTag,
  llmUserPrompt: userPrompt
} }];

const base = $('Build Project Index').item.json;
const out = $json.output || $json;
const mentioned = Array.isArray(out.mentioned_projects) ? out.mentioned_projects : [];
if (!mentioned.length) {
  return [{ json: { ...base, hasMentions: false, noActions: true } }];
}
const allActions = [];
for (const m of mentioned) {
  const actions = Array.isArray(m.actions) ? m.actions : [];
  for (const a of actions) {
    allActions.push({
      json: {
        ...base,
        hasMentions: true,
        project_client: m.project_client,
        action: a.action || 'update',
        existing_task_id: a.existing_task_id || null,
        task: a.task || '',
        status: a.status || null,
        latest_note: a.latest_note || '',
        next_step: a.next_step || '',
        lead: a.lead || '',
        meeting_id: null,
        calendar_event_id: base.calendar_event_id,
        errors: []
      }
    });
  }
}
if (!allActions.length) {
  return [{ json: { ...base, hasMentions: true, noActions: true } }];
}
return allActions;

const action = $('Switch Action').item.json;
const candidates = items.map(i => ({
  id: i.json.id,
  task: i.json.task,
  lead: i.json.lead,
  status: i.json.status,
  latest_note: i.json.latest_note || i.json.note,
  next_step: i.json.next_step
}));
const userPrompt = `You decide whether a newly proposed WIP task already exists in the current open task list for the same project_client. If yes, output decision=match with the existing task id and a confidence 0..1. Otherwise output decision=new.\n\nPROJECT_CLIENT: ${action.project_client}\n\nNEW TASK PROPOSAL:\n${JSON.stringify({ task: action.task, lead: action.lead, status: action.status, latest_note: action.latest_note, next_step: action.next_step }, null, 2)}\n\nEXISTING OPEN TASKS FOR THIS PROJECT:\n${JSON.stringify(candidates, null, 2)}\n\nReturn strict JSON: { "decision": "match" | "new", "match_id": "<uuid or null>", "confidence": <0..1>, "reason": "<short>" }`;
return [{ json: { ...action, candidates, matcherUserPrompt: userPrompt } }];

const action = $('Build WIP Match Prompt').item.json;
const m = $json.output || {};
const threshold = Number($('Merge System Config').item.json.wipConfidenceThreshold ?? 0.82);
const matched = m.decision === 'match' && m.match_id && Number(m.confidence || 0) >= threshold;
return [{
  json: {
    ...action,
    matcher: m,
    action: matched ? 'update' : 'create',
    existing_task_id: matched ? m.match_id : action.existing_task_id,
    matcherMatched: matched
  }
}];

const source = $('Switch Action').item.json;
const out = $json || {};
const err = out.error ? [out.error.message || JSON.stringify(out.error)] : [];
const id = out.id || source.existing_task_id || out.wip_task_id || null;
return [{ json: { ...source, wip_task_id: id, action_applied: source.action, errors: [...(source.errors || []), ...err] } }];

const context = $('Attach Meeting To Context').first().json;
const meeting = context.existing_meeting?.id ? context.existing_meeting : (context.meeting_id ? { id: context.meeting_id } : null);
const existingTasks = items.map(i => i.json).filter(r => r && r.wip_task_id);
const targetDate = $('Resolve Date').item.json.targetDate;
const createdToday = meeting?.created_at ? String(meeting.created_at).slice(0, 10) === targetDate : false;
return [{ json: { ...context, existing_meeting: meeting, meeting_exists: !!meeting, doubleRunWarning: !!meeting && createdToday && existingTasks.length > 0 } }];

const clean = $('Clean Transcript').item.json;
const row = $json || {};
const meeting_id = row.id || clean.meeting_id || null;
return [{ json: { ...clean, meeting_id, existing_meeting: row } }];

const action = $('Normalize WIP Result').item.json;
const guard = $('Check Double Run Guard').first().json;
const meeting_id = guard.meeting_id;
return [{ json: { ...action, meeting_id, missing_meeting_id: !meeting_id, existing_meeting: guard.existing_meeting || null, meeting_exists: !!guard.meeting_exists, doubleRunWarning: !!guard.doubleRunWarning } }];

const base = $('Attach Meeting ID').item.json;
const shouldCascade = base.action_applied === 'complete' && !!base.wip_task_id;
return [{ json: { ...base, shouldCascade, close_wip_task_id: shouldCascade ? base.wip_task_id : null } }];

const applied = $('Normalize WIP Result').all().map(i => i.json);
let cascades = [];
try { cascades = $('Cascade Close Tickets').all().map(i => i.json); } catch (e) { cascades = []; }
const counts = { tasks_created: 0, tasks_updated: 0, tasks_completed: 0, tickets_auto_closed: 0, errors: [], doubleRunWarning: false };
for (const a of applied) {
  if (a.action_applied === 'create') counts.tasks_created += 1;
  if (a.action_applied === 'update') counts.tasks_updated += 1;
  if (a.action_applied === 'complete') counts.tasks_completed += 1;
  if (a.doubleRunWarning) counts.doubleRunWarning = true;
  if (Array.isArray(a.errors)) counts.errors.push(...a.errors);
}
counts.tickets_auto_closed = cascades.filter(c => c && !c.error).length;
for (const c of cascades) if (c?.error) counts.errors.push(c.error.message || JSON.stringify(c.error));
return [{ json: { ...$('Resolve Date').item.json, ...counts } }];
